'use strict';
const KEY='jiyu-word-garden-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let state={progress:{},custom:[],edits:{},history:[],session:null,settings:{size:35,rate:.8,auto:false},schema:3,pausedSessions:{}},storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.progress&&Array.isArray(saved.custom)){state={...state,...saved,settings:{...state.settings,...saved.settings}};if(!saved.schema||saved.schema<3)state.settings.size=35;}}catch(e){storageOK=false}
if(!state.schema||state.schema<3){state.settings.size=35;state.schema=3;}
state.pausedSessions=state.pausedSessions||{};
if(state.session&&!state.session.key)state.session.key='legacy';
let page='today',query='',filter='all',editing=null,collectionFilter='all',selected=null,feedback='',wrongIds=[],modalWord=null;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){storageOK=false;toast('Storage is full or unavailable. Ask a grown-up to export a backup.');return false}}
function toast(t){const el=$('#toast');el.textContent=t;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3500)}
function allWords(){return [...WORDS.map(w=>({book:'Ivy + Bean · Book 1',...w,...state.edits[w.id]})),...state.custom]}
function getWord(id){return allWords().find(w=>w.id===id)}
function prog(id){return Learning.progress(state.progress[id]);}
function dueWords(){return Learning.rank(allWords().filter(w=>!prog(w.id).due||prog(w.id).due<=day()),state.progress,day());}
function trickyWords(){return Learning.rank(allWords().filter(w=>Learning.tricky(prog(w.id))),state.progress,day());}
function planned(){return Learning.plan(allWords(),state.progress,day(),state.settings.size);}
function stats(){const words=allWords();return {accuracy:Learning.accuracy(state.history),due:words.filter(w=>prog(w.id).due&&prog(w.id).due<=day()),tricky:trickyWords(),views:words.reduce((n,w)=>n+prog(w.id).views,0)};}
function newSession(ids,key,label){return {key,label,ids,round:1,index:0,stage:'cards',revealed:false,order:[...ids],matched:[],matchBatch:0,batchSize:5,quizIndex:0,wrong:[],matchWrong:[],quizAnswers:{},firstCorrect:0,review:false,checkIndex:0,checkWrong:[],checkAnswers:{},checkCorrect:0};}
function parkSession(){const old=state.session;if(old)state.pausedSessions[old.key||'legacy']=old;}
function launch(ids,key,label){if(!ids.length)return toast('Add a word to begin.');if(state.session?.key!==key){parkSession();const paused=state.pausedSessions[key];state.session=paused&&paused.ids.every(getWord)?paused:newSession(ids,key,label);delete state.pausedSessions[key];}page='today';save();renderSession();}
function metricsHTML(){const st=stats();return '<div class="stats stats-four"><div class="stat"><span class="symbol">🃏</span><div><b>'+state.history.length+'</b><small>Adventures finished</small></div></div><div class="stat"><span class="symbol">◎</span><div><b>'+(st.accuracy===null?'—':st.accuracy+'%')+'</b><small>First-try quiz accuracy</small></div></div><div class="stat"><span class="symbol">☀</span><div><b>'+st.due.length+'</b><small>Reviews due</small></div></div><div class="stat"><span class="symbol">🌱</span><div><b>'+st.tricky.length+'</b><small>Tricky words</small></div></div></div>';}
function mastered(){return allWords().filter(w=>prog(w.id).level>=3).length}
function streak(){let dates=[...new Set(state.history.map(h=>h.date))].sort().reverse(),n=0,d=new Date(day()+'T12:00:00Z');if(dates[0]!==day())d.setUTCDate(d.getUTCDate()-1);while(dates.includes(d.toISOString().slice(0,10))){n++;d.setUTCDate(d.getUTCDate()-1)}return n}
function btn(label,action,cls='secondary',attrs=''){return '<button class="'+cls+'" data-a="'+action+'" '+attrs+'>'+label+'</button>'}
function art(w,extra=''){if(w.image)return '<img class="customimage '+extra+'" src="'+esc(w.image)+'" alt="'+esc(w.imageAlt||w.meaning)+'">';let idx=Number.isInteger(w.atlasIndex)?w.atlasIndex:Number(w.id.replace('ivy-',''));if(!Number.isInteger(idx)||idx<0||idx>63)idx=63;const file=['atlas-part2-a.png','atlas-part2-b.png'].includes(w.atlas)?w.atlas:'atlas.png';return '<div role="img" aria-label="'+esc(w.meaning)+'" class="sprite '+extra+'" style="background-image:url('+file+');background-position:'+((idx%8)/7*100)+'% '+(Math.floor(idx/8)/7*100)+'%"></div>';}
function audio(text){if(!('speechSynthesis'in window)){toast('This browser cannot play speech. Try Safari or Chrome.');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=state.settings.rate;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-US'&&/Samantha|Google US|Jenny|Aria/.test(v.name))||voices.find(v=>v.lang==='en-US')||null;u.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast('Tap the sound button again, or check your device volume.')};speechSynthesis.speak(u)}
function speakButton(text,label='Hear word'){return '<button class="listen" data-a="speak" data-text="'+esc(text)+'" aria-label="'+esc(label)+'">♪</button>'}
function shell(content){$('#app').innerHTML='<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">✿</span><div>Word Garden<small>Made for Jiyu</small></div></div><nav class="nav" aria-label="Main navigation">'+[['today','☀','Today'],['words','▤','My words'],['garden','✿','My garden'],['parent','⚙','Grown-ups']].map(([p,i,t])=>'<button class="'+(page===p?'active':'')+'" data-a="nav" data-page="'+p+'"><i>'+i+'</i>'+t+'</button>').join('')+'</nav><div class="sidenote"><span style="font-size:35px">🌱</span><b>Little by little.</b>Every new word helps<br>your garden grow.</div></aside><main class="main"><header class="topbar"><span class="eyebrow">A little word adventure</span><div class="profile"><span class="avatar">🌷</span> Jiyu’s garden</div></header>'+content+'<div class="footer">Read. Imagine. Say it. Make it yours.</div></main></div>'}
function today(){const words=allWords(),cards=planned(),st=stats(),sets=Learning.sets(words),current=state.session;
const upcoming=words.filter(w=>prog(w.id).due).sort((a,b)=>prog(a.id).due.localeCompare(prog(b.id).due)).slice(0,8);
const setKeys=new Set(sets.map(set=>set.key));const savedGames=Object.entries(state.pausedSessions).filter(([key])=>!setKeys.has(key)&&key!=='adaptive');
const recent=[...words].reverse().sort((a,b)=>((Date.parse(b.addedAt)||0)-(Date.parse(a.addedAt)||0))).slice(0,6);
shell('<section class="hero compacthero"><div class="herotext"><span class="tag">YOUR WORD ADVENTURE</span><h1>Big words.<br>Little discoveries.</h1><p>A big, clear word first. Flip to see its story.</p>'+btn(current?.key==='adaptive'?'Continue '+current.ids.length+' words':'Play with '+cards.length+' words','start','primary','data-kind="adaptive"')+'<p class="bookhint">'+state.settings.size+' words at a time. Take a break whenever you like.</p></div><div class="heroart">'+art({id:'ivy-63',meaning:'An open book in a beautiful flower garden'})+'</div></section>'+metricsHTML()+
(current&&current.key!=='adaptive'?'<div class="resume-bar"><span>Saved adventure: <b>'+esc(current.label||current.ids.length+' words')+'</b></span>'+btn('Continue saved game','resume','smallbtn')+'</div>':'')+
savedGames.map(([key,game])=>'<div class="resume-bar"><span>Saved adventure: <b>'+esc(game.label||game.ids.length+' words')+'</b></span>'+btn('Continue saved adventure','resume','smallbtn','data-key="'+esc(key)+'"')+'</div>').join('')+
'<div class="sectionhead"><h2>Pick your word set</h2><span class="tag">'+words.length+' words collected</span></div><p class="muted">Part 1: 63 words · Part 2: 116 words · balanced sets of 30–40</p><div class="setgrid">'+sets.map((set,i)=>'<section class="setcard"><span class="eyebrow">IVY + BEAN 1 · '+set.label.toUpperCase()+'</span><h3>'+set.ids.length+' words</h3><p class="muted">'+esc(getWord(set.ids[0]).word)+' · '+esc(getWord(set.ids.at(-1)).word)+'</p>'+btn((current?.key===set.key||state.pausedSessions[set.key]?'Continue ':'Play ')+set.label,'playset','primary','data-set="'+i+'"')+'</section>').join('')+'</div>'+
'<div class="sectionhead"><h2>Your next '+cards.length+'</h2><span class="tag">Updates as you learn</span></div><div class="dailybox"><p class="muted">Tricky words first, then due reviews and new discoveries.</p><div class="wordchips">'+cards.map(w=>'<span class="chip">'+esc(w.word)+'</span>').join('')+'</div></div>'+
'<section class="panel"><div class="row"><h2>Coming up for review</h2><span class="spacer"></span><span class="tag">'+st.due.length+' due today</span></div><div class="wordchips">'+(upcoming.map(w=>'<button class="chip" data-a="openword" data-id="'+w.id+'"><b>'+esc(w.word)+'</b> <span class="muted">'+(prog(w.id).due<=day()?'Due now':prog(w.id).due)+'</span></button>').join('')||'<span class="muted">Your first adventure will plant a review date here.</span>')+'</div></section><div class="dashboard-bottom"><section class="panel"><div class="row"><h2>Needs a little sunshine</h2><span class="spacer"></span>'+btn('Practice tricky words','reviewlist','smallbtn',st.tricky.length?'':'disabled')+'</div><p class="muted">Words to meet again soon.</p><div class="wordchips">'+(st.tricky.slice(0,12).map(w=>btn(esc(w.word),'openword','chip','data-id="'+w.id+'"')).join('')||'<span class="muted">Your tricky words will appear here.</span>')+'</div></section><section class="panel"><h2>Recently collected</h2><div class="wordchips">'+recent.map(w=>btn(esc(w.word),'openword','chip','data-id="'+w.id+'"')).join('')+'</div><p class="bookhint">Add more from your next book in Grown-ups.</p></section></div>'+
'<div class="sectionhead"><h2>Your adventure path</h2></div><div class="journey journey-four">'+[['🃏','Flip & discover','See every word 3 times.'],['🧩','Find a match','Match every word in little groups.'],['◎','Pick a meaning','One word, four choices.'],['🌼','Quick check','Five little sentence puzzles.']].map(([i,t,d])=>'<div class="step"><div class="stepicon">'+i+'</div><h3>'+t+'</h3><p>'+d+'</p></div>').join('')+'</div>'+(!storageOK?'<p class="error">A local recovery copy is unavailable. Please check the server save status.</p>':''));
}
function start(){launch(planned().map(w=>w.id),'adaptive','Your next '+state.settings.size);}
function stages(s){const order=['cards','match','quiz','check'];return '<div class="steps">'+[1,2,3].map(r=>'<span class="'+(s.stage==='cards'?(s.round===r?'current':s.round>r?'done':''):'done')+'">Cards '+r+'/3</span>').join('')+[['match','Match'],['quiz','Quiz'],['check','Quick check']].map(([k,t])=>'<span class="'+(s.stage===k?'current':order.indexOf(s.stage)>order.indexOf(k)?'done':'')+'">'+t+'</span>').join('')+'</div>';}
function sessionHeader(s,sub){return '<div class="row">'+btn('Save & take a break','break','smallbtn')+'<span class="spacer"></span><span class="tag">'+esc(s.label||'Your saved adventure')+' · '+s.ids.length+' words</span></div>'+stages(s)+'<div class="studyhead"><h1>'+({cards:['','Meet your words','Say it with me','One more little look'][s.round],match:'Find the pairs',quiz:s.review?'Let’s try these again':'Pick the meaning',check:s.checkReview?'One more little try':'A little story check'}[s.stage])+'</h1><p class="muted">'+sub+'</p></div>';}
function gentle(w){return /unkind|name.*call|Story language/i.test(w.note||'')||['booger-head','dumb','tightwad','dork','wimp','a pain and a pest'].includes(w.word)?'<p class="hint">Story words can be unkind. Let’s use kind words with people.</p>':''}
function flashBody(w,reveal,mode='study'){if(!reveal)return '<section class="flip-card flash-front" aria-label="Flashcard front"><span class="eyebrow">WHAT DOES THIS WORD MEAN?</span><h2 class="focus-word">'+esc(w.word)+'</h2>'+speakButton(w.word)+'<p class="muted">Say it. Think it. Then flip.</p>'+btn('Flip the card','reveal','primary','aria-label="Flip the card"')+'</section>';
return '<section class="flip-card flash-back"><div class="back-title"><h2>'+esc(w.word)+'</h2>'+speakButton(w.word)+(mode==='study'?btn('Show word only','flipfront','smallbtn'):'')+'</div><div class="back-grid"><div class="visual-column">'+art(w)+MotionGuide.render(w)+'</div><div class="back-copy"><div class="meaning-block"><span class="content-label">MEANING</span><p class="meaning">'+esc(w.meaning)+'</p>'+speakButton(w.meaning,'Hear meaning')+'</div><div class="example"><span class="content-label">IN A SENTENCE</span><p>“'+esc(w.example)+'”</p>'+btn('♪ Hear the sentence','speak','smallbtn','data-text="'+esc(w.example)+'"')+'<p class="bookhint">'+esc(w.book||'My reading notebook')+' · '+esc(w.source)+'</p></div>'+gentle(w)+'</div></div></section>';}
function renderSession(){selected=null;const s=state.session;if(!s)return today();if(s.stage==='cards'){let w=getWord(s.order[s.index]);shell(sessionHeader(s,'First the word. Flip for the picture, meaning, and sentence.')+'<div class="row"><span class="muted">Round '+s.round+' of 3</span><span class="spacer"></span><span class="tag">Word '+(s.index+1)+' / '+s.ids.length+'</span></div><div class="progress"><i style="width:'+((s.index+s.ids.length*(s.round-1))/(s.ids.length*3)*100)+'%"></i></div>'+flashBody(w,s.revealed)+'<div class="controls">'+btn('Previous','prev','secondary',s.index===0?'disabled':'')+'<span class="muted cardtip">'+(s.revealed?'Say the word. Tell its story.':'Only the word. Let your mind imagine.')+'</span>'+btn(s.index===s.ids.length-1?(s.round===3?'Let’s match':'Next round'):'Next word','next','primary',s.revealed?'':'disabled')+'</div>');if(state.settings.auto)audio(w.word)}else if(s.stage==='match')renderMatch(s);else if(s.stage==='quiz')renderQuiz(s);else if(s.stage==='check')renderCheck(s);}
function next(){let s=state.session;if(!s||!s.revealed)return;s.index++;s.revealed=false;if(s.index>=s.ids.length){s.index=0;if(s.round===3){s.stage='match';s.matchOrder=shuffle(s.ids)}else{s.round++;s.order=shuffle(s.ids)}}save();renderSession()}
function batch(s){const size=s.batchSize||3;return s.ids.slice(s.matchBatch*size,s.matchBatch*size+size);}
function renderMatch(s){const ids=batch(s);if(!s.meaningOrder||!s.meaningOrder.every(id=>ids.includes(id)))s.meaningOrder=shuffle(ids);save();shell(sessionHeader(s,'Tap a word, then tap the meaning that fits. Pictures are resting!')+'<div class="gamebox"><div class="row"><span class="tag">Pairs '+s.matched.length+' / '+s.ids.length+'</span></div><div class="matchgrid"><div class="matchcol">'+shuffleStable(ids,s).map(id=>matchButton(id,'word',s)).join('')+'</div><div class="matchcol">'+s.meaningOrder.map(id=>matchButton(id,'meaning',s)).join('')+'</div></div><div class="feedback" role="status" id="feedback">Find a word and its meaning.</div>'+btn(s.matched.length===s.ids.length?'Ready for the quiz':'More pairs','matchnext','primary',ids.every(id=>s.matched.includes(id))?'':'disabled')+'</div>')}
function shuffleStable(ids,s){return (s.matchOrder||s.ids).filter(id=>ids.includes(id))}
function matchButton(id,type,s){let w=getWord(id),done=s.matched.includes(id);return '<button class="matchbtn '+(done?'matched':'')+'" data-a="pair" data-id="'+id+'" data-type="'+type+'" '+(done?'disabled':'')+'>'+esc(type==='word'?w.word:w.meaning)+'</button>'}
function pair(id,type,el){const s=state.session;if(!s||s.stage!=='match'||s.matched.includes(id))return;if(!selected||selected.type===type){document.querySelectorAll('.matchbtn.selected,.matchbtn.wrong').forEach(x=>x.classList.remove('selected','wrong'));selected={id,type,el};el.classList.add('selected');return}
if(id===selected.id){s.matched.push(id);selected.el.classList.remove('selected');selected.el.classList.add('matched');selected.el.disabled=true;el.classList.add('matched');el.disabled=true;$('#feedback').textContent='A lovely match!';const nextEl=$('[data-a="matchnext"]');if(batch(s).every(x=>s.matched.includes(x)))nextEl.disabled=false;nextEl.textContent=s.matched.length===s.ids.length?'Ready for the quiz':'More pairs';save()}else{for(const x of [id,selected.id])if(!s.matchWrong.includes(x)){s.matchWrong.push(x);markTricky(x);}el.classList.add('wrong');selected.el.classList.remove('selected');$('#feedback').textContent='Not quite. Read both meanings and try again.';save()}selected=null}
function quizIds(s){return s.review?s.wrong:s.ids}
function markTricky(id){const s=state.session,p=prog(id);s.markedErrors=s.markedErrors||[];if(!s.markedErrors.includes(id)){p.misses++;s.markedErrors.push(id);}p.needsReview=true;p.due=day();state.progress[id]=p;}
function tooSimilar(a,b){const groups=[['zip around','whiz','edge'],['jumpy','freaked out','wimp','froze'],['bug','a pain and a pest','drive someone crazy','bossy'],['meant','figure','hatch a plan'],['howl','wail','moan'],['mouth','mutter'],['limp','sprain'],['goony','dumb','weird','dork','booger-head'],['halt','froze'],['goony','goofy','dumb','weird','dork','dweeb','booger-head'],['squirming','squiggle','wiggle','waggle','wobble','back and forth'],['creep','sneak in','sneaky','slip past'],['a pain and a pest','bug','bugging','a pain in the kazoo','it’s driving me nuts','drive someone crazy'],['burst out laughing','giggle'],['yell','yelp','squeal','hiss','howl','wail','sob'],['goo','gloopy','ooze','mushy'],['glum','disappointed'],['barely','hardly']];return groups.some(g=>g.includes(a.word)&&g.includes(b.word))}
function renderQuiz(s){const ids=quizIds(s),id=ids[s.quizIndex],w=getWord(id);if(!w)return beginCheck();if(!s.options||!s.options.includes(id))s.options=shuffle([id,...shuffle(s.ids.map(getWord).filter(x=>x.id!==id&&x.meaning!==w.meaning&&!tooSimilar(x,w))).slice(0,3).map(x=>x.id)]);save();shell(sessionHeader(s,s.review?'Mistakes help us learn. Find the meaning one more time.':'Read the word. Choose the meaning. You can listen, too.')+'<div class="progress"><i style="width:'+(s.quizIndex/ids.length*100)+'%"></i></div><div class="gamebox"><div class="row"><span class="tag">Word '+(s.quizIndex+1)+' / '+ids.length+'</span><span class="spacer"></span><span class="bookhint">What does it mean?</span></div><div class="row" style="margin-top:20px"><h1 style="margin:0">'+esc(w.word)+'</h1>'+speakButton(w.word)+'</div><div class="answers">'+s.options.map((opt,i)=>'<button class="answer" data-a="answer" data-id="'+opt+'"><span class="muted">'+String.fromCharCode(65+i)+'.</span> '+esc(getWord(opt).meaning)+'</button>').join('')+'</div><div class="feedback" role="status" id="feedback" style="margin-top:18px">Take your time.</div>'+btn('Next word','quiznext','primary','disabled')+'</div>');if(s.answered){document.querySelectorAll('.answer').forEach(b=>{b.disabled=true;if(b.dataset.id===id)b.classList.add('good')});$('[data-a="quiznext"]').disabled=false;$('#feedback').textContent='Yes! That’s the meaning.'}}
function answer(id,el){let s=state.session;if(!s||s.stage!=='quiz'||s.answered)return;let correct=quizIds(s)[s.quizIndex],ok=id===correct;if(!s.review&&!Object.hasOwn(s.quizAnswers,correct)){s.quizAnswers[correct]=ok;if(ok)s.firstCorrect++;else if(!s.wrong.includes(correct)){s.wrong.push(correct);markTricky(correct);}}if(ok){el.classList.add('good');s.answered=true;document.querySelectorAll('.answer').forEach(b=>b.disabled=true);$('[data-a="quiznext"]').disabled=false;$('#feedback').textContent='Yes! That’s the meaning.'}else{el.classList.add('bad');el.disabled=true;$('#feedback').textContent='Keep exploring. Try another meaning.'}save()}
function quizNext(){let s=state.session;if(!s||!s.answered)return;s.answered=false;s.quizIndex++;s.options=null;if(s.quizIndex>=quizIds(s).length){if(!s.review&&s.wrong.length){s.review=true;s.quizIndex=0;save();return renderSession()}return beginCheck()}save();renderSession()}
function finish(){let s=state.session;if(!s)return;const result={date:day(),id:'session-'+Date.now(),label:s.label,ids:s.ids,correct:s.firstCorrect,total:s.ids.length,checkCorrect:s.checkCorrect||0,checkTotal:s.checkIds?.length||0,weak:[...new Set([...s.wrong,...s.matchWrong,...(s.checkWrong||[])])]};
s.ids.forEach(id=>{let p=prog(id),weak=result.weak.includes(id),checked=Object.hasOwn(s.checkAnswers||{},id);p={...p,level:weak?0:(p.lastSuccess===day()?p.level:Math.min(5,p.level+1)),lastSuccess:weak?p.lastSuccess:day(),lastPractice:day(),practices:p.practices+1,attempts:p.attempts+1,correct:p.correct+(s.quizAnswers[id]?1:0),checkAttempts:p.checkAttempts+(checked?1:0),checkCorrect:p.checkCorrect+(s.checkAnswers?.[id]?1:0),misses:weak?p.misses+(s.markedErrors?.includes(id)?0:1):Math.max(0,p.misses-1),needsReview:weak};p.due=Learning.nextDate(day(),p.level,weak);state.progress[id]=p;});state.history.push(result);delete state.pausedSessions[s.key];state.session=null;save();showResult(result);}
function showResult(r){shell('<div class="result"><div class="big">🌼</div><span class="eyebrow">A little more grown</span><h1>You did it, Jiyu!</h1><p>You gave '+r.total+' words a little sunshine today.</p><div class="row"><span class="badge">3 card rounds</span><span class="badge">All pairs matched</span><span class="badge">Quick check done</span></div><p style="margin-top:20px"><b>'+r.correct+' / '+r.total+'</b> right on the first quiz try</p><p><b>'+r.checkCorrect+' / '+r.checkTotal+'</b> first-try story checks</p><p class="muted">'+(r.weak.length?'We’ll see the tricky words again tomorrow.':'Lovely growing! Your next list is ready.')+'</p><div class="resultwords">'+r.ids.map(id=>'<div><b>'+esc(getWord(id)?.word||id)+'</b><span>'+(r.weak.includes(id)?'🌱 Still growing':'🌷 Growing well')+'</span></div>').join('')+'</div><div class="row">'+btn('See my dashboard','nav','primary','data-page="today"')+btn('Practice tricky words','retry','secondary',r.weak.length?'data-ids="'+r.weak.join(',')+'"':'disabled')+'</div></div>');}
function wordsPage(){let words=allWords().filter(w=>(collectionFilter==='all'||(w.collection||'mywords')===collectionFilter)&&(w.word+' '+w.meaning).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||filter==='tricky'&&Learning.tricky(prog(w.id))||filter==='blooming'&&prog(w.id).level>=3));shell('<span class="eyebrow">Your reading collection</span><h1>So many words to discover.</h1><p class="muted">Your reading notebook · '+allWords().length+' words and phrases</p><div class="filterbar"><select class="search" id="collectionFilter" aria-label="Choose reading list">'+[['all','All reading lists'],['part1','Ivy + Bean 1 · Part 1'],['part2','Ivy + Bean 1 · Part 2'],['mywords','My added words']].map(([v,t])=>'<option value="'+v+'" '+(collectionFilter===v?'selected':'')+'>'+t+'</option>').join('')+'</select><input class="search" id="search" placeholder="Find a word…" value="'+esc(query)+'" aria-label="Find a word">'+[['all','All words'],['tricky','Still growing'],['blooming','Blooming']].map(([v,t])=>btn(t,'filter',filter===v?'smallbtn':'secondary','data-filter="'+v+'"')).join('')+'</div><div class="wordgrid">'+words.map(w=>'<button class="wordtile" data-a="openword" data-id="'+w.id+'"><div class="tilebody"><b>'+esc(w.word)+'</b><small>'+ (prog(w.id).level>=3?'🌼 Blooming':prog(w.id).level>0?'🌱 Growing':'Ready to discover')+'</small></div></button>').join('')+'</div>'+(!words.length?'<div class="empty">No words here yet.</div>':''))}
function gardenPage(){shell('<span class="eyebrow">Little things grow</span><h1>Look at your word garden!</h1><p class="muted">A seed becomes a flower with practice on different days.</p><div class="panel row"><span>○ New</span><span>🌱 First practice</span><span>🌿 Growing</span><span>🌼 Blooming after 3 strong practices</span></div><div class="garden">'+allWords().map(w=>'<button class="flower" data-a="openword" data-id="'+w.id+'"><b>'+(['○','🌱','🌿','🌼','🌷','🌻'][prog(w.id).level]||'○')+'</b><small>'+esc(w.word)+'</small></button>').join('')+'</div><div class="sectionhead"><h2>Your growing days</h2><span class="tag">'+state.history.length+' adventures</span></div><div class="dailybox">'+(state.history.slice(-7).reverse().map(h=>'<p><b>'+esc(h.date)+'</b> · '+h.total+' words · '+h.correct+'/'+h.total+' on the first try</p>').join('')||'<p class="muted">Your first adventure is waiting.</p>')+'</div>')}

function checkData(w){const canonical=WORDS.find(x=>x.id===w.id);if(w.check&&w.word===canonical?.word&&w.meaning===canonical?.meaning)return w.check;let index=Number(w.id.replace('ivy-',''));if(w.id.startsWith('ivy-')&&CHECK_PROMPTS[index]&&w.word===WORDS[index].word&&w.meaning===WORDS[index].meaning)return {prompt:CHECK_PROMPTS[index][0],form:CHECK_PROMPTS[index][1]};return {prompt:w.meaning,form:w.word,reverse:true};}
function beginCheck(){const s=state.session;s.stage='check';s.answered=false;s.options=null;s.checkIndex=0;s.checkWrong=[];s.checkAnswers={};s.checkCorrect=0;s.checkIds=[...new Set([...s.wrong,...s.matchWrong,...shuffle(s.ids)])].slice(0,Math.min(5,s.ids.length));save();renderSession();}
function checkIds(s){return s.checkReview?s.checkWrong:s.checkIds;}
function renderCheck(s){const ids=checkIds(s),id=ids[s.checkIndex],w=getWord(id);if(!w)return finish();const q=checkData(w);if(!s.options||!s.options.includes(id)){const seen=new Set([q.form.toLowerCase()]);const pool=shuffle(s.ids.map(getWord).filter(x=>x.id!==id&&!tooSimilar(x,w))).filter(x=>{const f=checkData(x).form.toLowerCase();if(seen.has(f))return false;seen.add(f);return true;});s.options=shuffle([id,...pool.slice(0,3).map(x=>x.id)]);}save();shell(sessionHeader(s,q.reverse?'Read the meaning. Find the word.':'Choose the missing word. These are little practice sentences.')+'<div class="gamebox"><div class="row"><span class="tag">Check '+(s.checkIndex+1)+' / '+ids.length+'</span><span class="spacer"></span><span class="bookhint">No timer. Just think.</span></div><div class="check-prompt">'+esc(q.prompt).replace('___','<span class="blank" aria-label="blank">…</span>')+'</div><div class="answers">'+s.options.map((opt,i)=>'<button class="answer" data-a="checkanswer" data-id="'+opt+'">'+String.fromCharCode(65+i)+'. '+esc(q.reverse?getWord(opt).word:checkData(getWord(opt)).form)+'</button>').join('')+'</div><div class="feedback" id="feedback" role="status">Which word fits?</div>'+btn('Next check','checknext','primary',s.answered?'':'disabled')+'</div>');if(s.answered){document.querySelectorAll('.answer').forEach(b=>{b.disabled=true;if(b.dataset.id===id)b.classList.add('good')});$('#feedback').textContent='Yes! That fits the story.';}}
function checkAnswer(id,el){const s=state.session;if(!s||s.stage!=='check'||s.answered)return;const current=checkIds(s)[s.checkIndex],ok=id===current;if(!s.checkReview&&!Object.hasOwn(s.checkAnswers,current)){s.checkAnswers[current]=ok;if(ok)s.checkCorrect++;else if(!s.checkWrong.includes(current)){s.checkWrong.push(current);markTricky(current);}}if(ok){s.answered=true;el.classList.add('good');document.querySelectorAll('.answer').forEach(b=>b.disabled=true);$('[data-a="checknext"]').disabled=false;$('#feedback').textContent='Yes! That fits the story.';}else{el.classList.add('bad');el.disabled=true;$('#feedback').textContent='Read the little story again. Try another word.';}save();}
function checkNext(){const s=state.session;if(!s?.answered)return;s.answered=false;s.options=null;s.checkIndex++;if(s.checkIndex>=checkIds(s).length){if(!s.checkReview&&s.checkWrong.length){s.checkReview=true;s.checkIndex=0;}else return finish();}save();renderSession();}
function parentProgress(){const st=stats(),ranked=Learning.rank(allWords(),state.progress,day());return '<section class="panel"><h2>지유의 학습 현황</h2>'+metricsHTML()+'<p>카드 확인 <b>'+st.views+'회</b> · 연속 학습 <b>'+streak()+'일</b> · 3단계 이상 익힌 단어 <b>'+mastered()+'개</b></p><p class="bookhint">정답률은 첫 답변 기준입니다. 카드 확인 횟수와 단어별 정답률은 이번 업데이트부터 기록하며, 기존 완료 학습과 전체 퀴즈 정답률은 유지합니다.</p><div class="table-scroll"><table><thead><tr><th>단어</th><th>카드 확인</th><th>완료 학습</th><th>퀴즈 첫 답</th><th>문장 확인 첫 답</th><th>복습일</th><th>상태</th></tr></thead><tbody>'+ranked.map(w=>{const p=prog(w.id);return '<tr><td><b>'+esc(w.word)+'</b></td><td>'+p.views+'회</td><td>'+p.practices+'회</td><td>'+(p.attempts?Math.round(p.correct/p.attempts*100)+'%':'—')+'</td><td>'+(p.checkAttempts?Math.round(p.checkCorrect/p.checkAttempts*100)+'%':'—')+'</td><td>'+esc(p.due||'새 단어')+'</td><td>'+(Learning.tricky(p)?'우선 복습':p.level>=3?'익힘':p.lastPractice?'학습 중':'시작 전')+'</td></tr>';}).join('')+'</tbody></table></div><h3 style="margin-top:22px">최근 완료 기록</h3>'+ (state.history.slice(-5).reverse().map(h=>'<p>'+esc(h.date)+' · '+h.total+'개 · 퀴즈 '+h.correct+'/'+h.total+(h.checkTotal?' · 확인 문제 '+h.checkCorrect+'/'+h.checkTotal:'')+'</p>').join('')||'<p class="muted">아직 완료한 학습이 없습니다.</p>')+'<h3 style="margin-top:22px">다음 학습 목록 · '+planned().length+'개</h3><div class="wordchips">'+planned().map(w=>'<span class="chip">'+esc(w.word)+'</span>').join('')+'</div><p class="bookhint">단어를 추가하거나 학습을 마치면 어려운 단어 → 복습일이 된 단어 → 새 단어 → 추가 연습 순으로 목록을 다시 계산합니다. 진행 중인 게임의 단어는 끝날 때까지 유지합니다.</p></section>';}

function parentPage(){let w=editing?getWord(editing):null;shell('<span class="eyebrow">Grown-up corner</span><h1>A garden made just for Jiyu.</h1><p class="muted">단어와 책 문장은 부모가 넣고, 지유는 영어로만 배워요.</p>'+parentProgress()+'<div class="panel"><h2>학습 설정</h2><p class="bookhint">기본 단어 '+WORDS.length+'개 (앞부분 63개 + 뒷부분 116개) · AR 2.7–3.5 독서 수준을 고려한 쉬운 영영풀이</p><div class="form"><label>한 번에 학습할 단어 수<select id="size">'+[30,35,40].map(n=>'<option '+(state.settings.size===n?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>발음 속도<select id="rate">'+[[.65,'천천히'],[.8,'보통보다 천천히'],[1,'자연스럽게']].map(([v,t])=>'<option value="'+v+'" '+(state.settings.rate===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label class="wide"><span><input type="checkbox" id="auto" '+(state.settings.auto?'checked':'')+' style="width:auto"> 카드를 열 때 단어 자동 발음 (기기에서 허용될 때)</span></label></div><p class="bookhint">세트는 30~40개씩 고르게 나누며 하루 횟수 제한은 없습니다. 각 단어를 3회 본 뒤 매칭·퀴즈·짧은 문장 확인 문제로 점검합니다. 틀린 단어는 당일 다시 풀고 다음 날 우선 복습합니다. 정답 단어는 1·3·7·14·30일 간격으로 복습합니다. 설정은 다음 학습부터 적용됩니다.</p>'+btn('설정 저장','settings','primary')+'</div><div class="panel"><h2>'+ (w?'단어 수정':'새 단어 추가')+'</h2><p class="bookhint">자동 AI 생성 기능은 연결되어 있지 않습니다. 새 단어는 영영풀이와 그림도 함께 입력해 주세요.</p><form id="wordform" class="form"><label>Word / phrase<input id="word" required value="'+esc(w?.word||'')+'"></label><label>Easy English meaning<input id="meaning" required value="'+esc(w?.meaning||'')+'"></label><label class="wide">Book title (optional)<input id="book" value="'+esc(w?.book||'')+'"></label><label class="wide">Book sentence<textarea id="example" required>'+esc(w?.example||'')+'</textarea></label><label>Example source<select id="source"><option '+(w?.source==='From your reading notes'?'selected':'')+'>From your reading notes</option><option '+(w?.source!=='From your reading notes'?'selected':'')+'>Practice / check book</option></select></label><label>Picture (JPG, PNG, WebP · 최대 2 MB)<input id="picture" type="file" accept="image/png,image/jpeg,image/webp" '+(!w?'required':'')+'></label><label class="wide">Picture description in English<input id="imageAlt" value="'+esc(w?.imageAlt||w?.meaning||'')+'" required></label><label class="wide">부모 메모 / 교정 사항<textarea id="note">'+esc(w?.note||'')+'</textarea></label><div class="wide row"><button class="primary" type="submit">'+(w?'변경 저장':'단어 추가')+'</button>'+btn('새 단어 작성','newword','secondary')+'</div></form></div><div class="panel"><h2>원문 확인과 단어 관리</h2><p>책 원문을 직접 대조하지 못했습니다. 입력하신 문장은 최대한 유지했고, 오타 교정·문맥 추정·새로 만든 예문은 아래에 표시했습니다. 그림은 AI로 만든 학습용 삽화입니다.</p><div class="parentlist">'+allWords().map(w=>'<div class="parentitem">'+btn('수정','edit','smallbtn','data-id="'+w.id+'"')+'<b>'+esc(w.word)+'</b><p>'+esc(w.example)+'</p>'+(w.note?'<p class="muted">'+esc(w.note)+'</p>':'')+'</div>').join('')+'</div></div><div class="panel"><h2>백업과 기기 이동</h2><p>단어·그림·진도는 가족 계정의 서버에 저장됩니다. 다른 기기에서 같은 계정으로 로그인하면 이어서 사용할 수 있어요. 화면 위의 저장 완료 표시를 확인해 주세요. 기존 Sites 기록은 그 사이트에서 백업한 파일을 여기서 가져와야 합니다.</p><div class="row">'+btn('백업 다운로드','export','primary')+'<label class="secondary" style="cursor:pointer">백업 가져오기<input id="import" type="file" accept="application/json" hidden></label></div><p class="bookhint">가져오기는 단어를 합치고 동일한 단어의 진도·설정은 백업 값으로 갱신합니다. 현재 게임이 없으면 백업 속 게임 위치도 복원합니다. 가져온 내용은 서버에도 저장됩니다.</p></div>')}
function openWord(id){let w=getWord(id);if(!w)return;modalWord=id;let m=document.createElement('div');m.className='modal';m.id='wordmodal';m.innerHTML='<div class="modalbox" role="dialog" aria-modal="true" aria-label="'+esc(w.word)+'"><div class="row" style="margin-bottom:15px"><span class="eyebrow">Take a little look</span><span class="spacer"></span>'+btn('Close','closemodal','smallbtn')+'</div><div class="modal-card">'+flashBody(w,false,'browse')+'</div></div>';document.body.appendChild(m);$('[data-a="closemodal"]').focus()}
function render(){if(page==='today')today();else if(page==='words')wordsPage();else if(page==='garden')gardenPage();else parentPage()}
const actions={
nav:e=>{page=e.dataset.page;render()},start,
resume:e=>{if(e?.dataset.key&&state.pausedSessions[e.dataset.key]){const saved=state.pausedSessions[e.dataset.key];parkSession();state.session=saved;delete state.pausedSessions[e.dataset.key];save();}page='today';renderSession()},
playset:e=>{const i=Number(e.dataset.set),set=Learning.sets(allWords())[i];if(set)launch(set.ids,set.key,set.label);},
reviewlist:()=>{const ids=trickyWords().slice(0,30).map(w=>w.id);launch(ids,'tricky-'+day(),'Tricky words');},
checkanswer:e=>checkAnswer(e.dataset.id,e),checknext:checkNext,break:()=>{save();today()},reveal:()=>{if(modalWord){const w=getWord(modalWord);$('#wordmodal .modal-card').innerHTML=flashBody(w,true,'browse');return;}const s=state.session;if(!s)return;const id=s.order[s.index],p=prog(id);p.views++;state.progress[id]=p;s.revealed=true;save();renderSession()},flipfront:()=>{state.session.revealed=false;save();renderSession()},next,
prev:()=>{let s=state.session;if(s&&s.index>0){s.index--;s.revealed=false;save();renderSession()}},
motion:e=>{const panel=e.closest('.motion-guide'),playing=panel.classList.toggle('playing');e.textContent=playing?'Pause motion':'Play motion';e.setAttribute('aria-pressed',String(playing));},speak:e=>audio(e.dataset.text),pair:e=>pair(e.dataset.id,e.dataset.type,e),matchnext:()=>{let s=state.session;if(!batch(s).every(id=>s.matched.includes(id)))return;selected=null;if(s.matched.length===s.ids.length)s.stage='quiz';else{s.matchBatch++;s.meaningOrder=null}save();renderSession()},answer:e=>answer(e.dataset.id,e),quiznext:quizNext,
filter:e=>{filter=e.dataset.filter;wordsPage()},openword:e=>openWord(e.dataset.id),closemodal:()=>{$('#wordmodal')?.remove();modalWord=null},
settings:()=>{state.settings={size:Number($('#size').value),rate:Number($('#rate').value),auto:$('#auto').checked};save();toast('설정을 저장했어요.')},
edit:e=>{editing=e.dataset.id;parentPage();$('#wordform').scrollIntoView({behavior:'smooth',block:'start'})},newword:()=>{editing=null;parentPage();$('#wordform').scrollIntoView({block:'start'})},
retry:e=>{let ids=e.dataset.ids.split(',').filter(getWord);launch(ids,'retry-'+Date.now(),'A little extra practice')}, 
export:()=>{let blob=new Blob([JSON.stringify({...state,exported:day()},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='jiyu-word-garden-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('백업 파일을 저장해 주세요.')}
};
document.addEventListener('click',e=>{let el=e.target.closest('[data-a]');if(el&&!el.disabled&&actions[el.dataset.a])actions[el.dataset.a](el);else if(!el&&e.target.closest('.flash-front'))actions.reveal()});
document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;query=e.target.value;wordsPage();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')actions.closemodal();if(e.key==='Tab'&&$('#wordmodal')){let nodes=[...$('#wordmodal').querySelectorAll('button')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function validImportedSession(s){const known=new Set(allWords().map(w=>w.id));return s&&typeof s==='object'&&['cards','match','quiz','check'].includes(s.stage)&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.every(id=>known.has(id))&&Array.isArray(s.order)&&s.order.length===s.ids.length&&s.order.every(id=>s.ids.includes(id))&&[1,2,3].includes(s.round)&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.ids.length;}
function fileData(file){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
document.addEventListener('submit',async e=>{if(e.target.id!=='wordform')return;e.preventDefault();let old=editing?getWord(editing):null,file=$('#picture').files[0],image=old?.image||'';if(file){if(file.size>2*1024*1024||!/^image\/(png|jpeg|webp)$/.test(file.type))return toast('2 MB 이하의 PNG, JPG, WebP 그림을 선택해 주세요.');image=await fileData(file)}const w={id:editing||'custom-'+Date.now(),word:$('#word').value.trim(),meaning:$('#meaning').value.trim(),example:$('#example').value.trim(),book:$('#book').value.trim(),addedAt:old?.addedAt||new Date().toISOString(),source:$('#source').value,note:$('#note').value.trim(),image,imageAlt:$('#imageAlt').value.trim()};if(!w.word||!w.meaning||!w.example||!w.imageAlt||!old&&!image)return toast('단어·영영풀이·예문·그림 설명과 그림을 확인해 주세요.');let before=JSON.stringify(state);if(/^ivy(?:2)?-/.test(editing||''))state.edits[editing]={...w};else if(editing)state.custom=state.custom.map(x=>x.id===editing?w:x);else state.custom.push(w);if(!save()){state=JSON.parse(before);return}editing=null;parentPage();toast('단어를 저장했어요.')});
document.addEventListener('change',async e=>{if(e.target.id==='collectionFilter'){collectionFilter=e.target.value;wordsPage();return;}if(e.target.id!=='import')return;let f=e.target.files[0];if(!f)return;if(f.size>15*1024*1024)return toast('백업 파일이 너무 큽니다.');try{let d=JSON.parse(await f.text());if(!d.progress||!Array.isArray(d.custom)||!Array.isArray(d.history)||!d.edits)throw Error();const valid=w=>w&&typeof w.word==='string'&&typeof w.meaning==='string'&&typeof w.example==='string'&&/^custom-\d+$/.test(w.id)&&(!w.image||/^data:image\/(png|jpeg|webp);base64,/.test(w.image));if(!d.custom.every(valid))throw Error();for(let [id,w]of Object.entries(d.edits)){if(!/^ivy(?:2)?-\d+$/.test(id)||!w||typeof w.word!=='string'||typeof w.meaning!=='string'||typeof w.example!=='string'||w.image&&!/^data:image\/(png|jpeg|webp);base64,/.test(w.image))throw Error()}for(let p of Object.values(d.progress))if(!Number.isInteger(p.level)||p.level<0||p.level>5||typeof p.due!=='string'||!Number.isFinite(p.misses)||p.due&&!/^\d{4}-\d{2}-\d{2}$/.test(p.due)||['views','practices','attempts','correct','checkAttempts','checkCorrect'].some(k=>p[k]!==undefined&&(!Number.isInteger(p[k])||p[k]<0)))throw Error();let before=JSON.stringify(state);const map=new Map(state.custom.map(w=>[w.id,w]));d.custom.forEach(w=>map.set(w.id,w));state.custom=[...map.values()];state.edits={...state.edits,...d.edits};state.progress={...state.progress,...d.progress};state.history=[...new Map([...state.history,...d.history.filter(h=>h&&Array.isArray(h.ids)&&typeof h.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(h.date)&&h.ids.every(id=>typeof id==='string')&&Number.isInteger(h.total)&&h.total>0&&Number.isInteger(h.correct)&&h.correct>=0&&h.correct<=h.total)].map(h=>[h.id||h.date+':'+h.ids.join(',')+':'+h.correct,h])).values()];if(d.settings)state.settings={size:[30,35,40].includes(d.settings.size)?d.settings.size:35,rate:[.65,.8,1].includes(d.settings.rate)?d.settings.rate:.8,auto:!!d.settings.auto};if(!state.session&&validImportedSession(d.session))state.session=d.session;state.pausedSessions=state.pausedSessions||{};for(const [key,game]of Object.entries(d.pausedSessions||{})){if(/^[a-zA-Z0-9._-]{1,100}$/.test(key)&&!state.pausedSessions[key]&&validImportedSession(game))state.pausedSessions[key]=game;}if(!save()){state=JSON.parse(before);return}parentPage();toast('백업을 가져왔어요. 서버 저장 표시도 확인해 주세요.')}catch(err){toast('올바른 Word Garden 백업 파일을 선택해 주세요.')}});
render();
